import java.util.*;
import java.io.*;

public class Main {
    static final int P = 998244353;
    static final int MOD = 1000000007;
    static final int B = 1000000;
    static long total_count = 0;
    static long current = 0;
    static long[] prefix_sum = new long[7];
    static int result = 0;
    static List<Integer>[] sequences = new ArrayList[7];

    static {
        for (int i = 0; i < 7; i++) {
            sequences[i] = new ArrayList<>();
        }
    }

    static int normalize_mod(long d) {
        long res = d % P;
        if (res < 0) res += P;
        return (int) res;
    }

    static void build(int level, long val) {
        total_count++;
        sequences[level].add(normalize_mod(total_count - val));
        if (level < 6) {
            for (int i = 0; i <= 9; i++) {
                build(level + 1, val * 10 + i);
            }
        }
    }

    static int get(int id, int f) {
        List<Integer> seq = sequences[id];
        int pos = lowerBound(seq, P - f);
        long sum = 0;
        for (int j = 0; j < pos; j++) {
            sum += seq.get(j);
        }
        long res = ((long)f * seq.size() + prefix_sum[id] - (long)P * (seq.size() - pos)) % MOD;
        if (res < 0) res += MOD;
        return (int) res;
    }

    static int lowerBound(List<Integer> list, int value) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) >= value) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    static void dfs(int depth, long v) {
        if (v > total_count) return;
        if (depth >= 1) {
            if (v * B > total_count / 10 && v * B + B - 1 <= total_count) {
                int t = 1;
                for (int i = 0; i <= 6; i++) {
                    result = (result + get(i, normalize_mod(current - v * t))) % MOD;
                    t *= 10;
                }
                for (int i = 0; i <= 6; i++) {
                    current += sequences[i].size();
                }
                return;
            }
            result = (result + normalize_mod(++current - v)) % MOD;
        }
        for (int i = (depth == 0 ? 0 : 0); i <= 9; i++) {
            dfs(depth + 1, v * 10 + i);
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        long n_input = Long.parseLong(br.readLine());
        build(0, 0);
        for (int i = 0; i <= 6; i++) {
            Collections.sort(sequences[i]);
            for (int j = 0; j < sequences[i].size(); j++) {
                prefix_sum[i] += sequences[i].get(j);
            }
        }
        current = 0;
        dfs(0, 0);
        System.out.println(result);
    }
}
